<script lang="ts">
	import { onMount } from 'svelte';
	import { base } from '$app/paths';
	import type { SessionSummary } from '$lib/api';
	import { fetchSessions } from '$lib/api';
	import { isStaticMode } from '$lib/stores/mode.svelte';
	import { formatElapsed, formatAge } from '$lib/components/board/board-utils';
	import { Badge } from '$lib/components/ui/badge';
	import Activity from '@lucide/svelte/icons/activity';

	let sessions = $state<SessionSummary[]>([]);
	let loading = $state(true);
	let error = $state('');

	async function loadSessions() {
		loading = true;
		error = '';
		try {
			const data = await fetchSessions();
			sessions = data.items;
		} catch (err) {
			error = err instanceof Error ? err.message : 'Failed to load sessions';
		} finally {
			loading = false;
		}
	}

	function statusColor(status: string): string {
		switch (status) {
			case 'active':
				return 'bg-status-in-progress text-status-in-progress-fg';
			case 'completed':
				return 'bg-status-completed text-status-completed-fg';
			case 'failed':
				return 'bg-status-blocked text-status-blocked-fg';
			default:
				return 'bg-status-cancelled text-status-cancelled-fg';
		}
	}

	onMount(() => {
		loadSessions();
	});
</script>

