  6→  AC: @ui-task-board ac-5 — Real-time WebSocket updates
  7→  AC: @ui-task-board ac-6 — Task action buttons in modal
  8→-->
  9→<script lang="ts">
 10→	import { page } from '$app/stores';
 11→	import { onMount, onDestroy } from 'svelte';
 12→	import type { TaskSummary, BroadcastEvent } from '@kynetic-ai/shared';
 13→	import { fetchTasks, fetchAgentStatus, type AgentStatus } from '$lib/api';
 14→	import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 15→	import { getProjectVersion } from '$lib/stores/project.svelte';
 16→	import { distributeToColumns, type BoardColumn } from '$lib/components/board/board-utils';
 17→	import BoardColumnComponent from '$lib/components/board/BoardColumn.svelte';
 18→	import ActiveFleetRow from '$lib/components/board/ActiveFleetRow.svelte';
 19→	import TaskDetailModal from '$lib/components/board/TaskDetailModal.svelte';
 20→	import BoardSkeleton from '$lib/components/board/BoardSkeleton.svelte';
 21→	import LayoutGrid from '@lucide/svelte/icons/layout-grid';
 22→	import List from '@lucide/svelte/icons/list';
 23→	import { Button } from '$lib/components/ui/button';
 24→	import { base } from '$app/paths';
 25→
 26→	let tasks = $state<TaskSummary[]>([]);
 27→	let columns = $state<BoardColumn[]>([]);
 28→	let loading = $state(true);
 29→	let error = $state('');
 30→	let agentStatus = $state<AgentStatus | null>(null);
 31→
 32→	// AC: @ui-task-board ac-4 — Accumulated output lines per agent session
 33→	const MAX_OUTPUT_LINES = 3;
 34→	let agentOutputLines = $state<Record<string, string[]>>({});
 35→
 36→	// Detail modal state
 37→	let modalOpen = $state(false);
 38→	let selectedTaskRef = $state<string | null>(null);
 39→
 40→	// Track last processed URL ref to avoid infinite loops
 41→	let lastProcessedRef = $state('');
 42→
 43→	$effect(() => {
 44→		// Re-derive columns whenever tasks change
 45→		columns = distributeToColumns(tasks);
 46→	});
 47→
 48→	// AC: @ui-task-board ac-5 — Reload on project change
 49→	$effect(() => {
 50→		const version = getProjectVersion();
 51→		if (version > 0) {
 52→			loadBoard();
 53→		}
 54→	});
 55→
 56→	// Open task detail from URL param
 57→	$effect(() => {
 58→		const urlRef = $page.url.searchParams.get('ref');
 59→		if (urlRef && urlRef !== lastProcessedRef) {
 60→			lastProcessedRef = urlRef;
 61→			selectedTaskRef = urlRef;
 62→			modalOpen = true;
 63→		}
 64→	});
 65→
 66→	async function loadBoard() {
 67→		loading = true;
 68→		error = '';
 69→		try {
 70→			const [taskResponse, statusResponse] = await Promise.all([
 71→				fetchTasks({ limit: 500 }),
 72→				fetchAgentStatus().catch(() => null)
 73→			]);
 74→			tasks = taskResponse.items;
 75→			agentStatus = statusResponse;
 76→		} catch (err) {
 77→			error = err instanceof Error ? err.message : 'Failed to load board';
 78→		} finally {
 79→			loading = false;
 80→		}
 81→	}
 82→
 83→	function handleCardClick(task: TaskSummary) {
 84→		selectedTaskRef = task._ulid;
 85→		modalOpen = true;
 86→	}
 87→
 88→	function handleTaskUpdated() {
 89→		loadBoard();
 90→	}
 91→
 92→	// AC: @ui-task-board ac-5 — WebSocket real-time updates
 93→	function handleTaskUpdate(event: BroadcastEvent) {
 94→		loadBoard();
 95→	}
 96→
 97→	// AC: @ui-task-board ac-4 — Refresh agent status on agent events
 98→	function handleAgentUpdate(event: BroadcastEvent) {
 99→		// AC: @ui-task-board ac-4 — Accumulate text chunks for last few lines of output
100→		if (event.event === 'agent_text_chunk' && event.data?.session_id && event.data?.text) {
101→			const sessionId = event.data.session_id as string;
102→			const text = event.data.text as string;
103→			const newLines = text.split('\n').filter((l: string) => l.trim().length > 0);
104→			if (newLines.length > 0) {
105→				const existing = agentOutputLines[sessionId] ?? [];
106→				agentOutputLines[sessionId] = [...existing, ...newLines].slice(-MAX_OUTPUT_LINES);
107→			}
108→			return;
109→		}
110→
111→		// Invocation lifecycle events — refresh status and clean up stale output
112→		fetchAgentStatus()
113→			.then((status) => {
114→				agentStatus = status;
115→				// Clean up output lines for sessions no longer active
116→				const activeSessions = new Set(
117→					status.active_invocations.map((inv) => inv.session_id)
118→				);
119→				for (const sessionId of Object.keys(agentOutputLines)) {
120→					if (!activeSessions.has(sessionId)) {
121→						delete agentOutputLines[sessionId];
122→					}
123→				}
124→			})
125→			.catch(() => {});
126→	}
127→
128→	// Polling for agent elapsed time updates
129→	let agentPollTimer: ReturnType<typeof setInterval> | undefined;
130→
131→	onMount(() => {
132→		loadBoard();
133→
134→		// AC: @ui-task-board ac-5 — Subscribe to task and agent updates
135→		subscribe(['tasks', 'agents']);
136→		on('tasks', handleTaskUpdate);
137→		on('agents', handleAgentUpdate);
138→
139→		// Poll agent status every 5s for elapsed time updates
140→		agentPollTimer = setInterval(() => {
141→			fetchAgentStatus()
142→				.then((status) => {
143→					agentStatus = status;
144→				})
145→				.catch(() => {});
146→		}, 5000);
147→	});
148→
149→	onDestroy(() => {
150→		off('tasks', handleTaskUpdate);
151→		off('agents', handleAgentUpdate);
152→		unsubscribe(['tasks', 'agents']);
153→		if (agentPollTimer) clearInterval(agentPollTimer);
154→	});
155→</script>
156→
157→<div class="flex flex-col h-full">
158→	<!-- Header -->
159→	<div class="flex items-center justify-between p-6 pb-0">
160→		<div>
161→			<h1 class="text-2xl font-bold">Task Board</h1>
162→			{#if !loading && tasks.length > 0}
163→				<p class="text-sm text-muted-foreground">{tasks.length} tasks</p>
164→			{/if}
165→		</div>
166→
167→		<!-- View toggle: Board / List -->
168→		<div class="flex items-center gap-1 border rounded-lg p-0.5">
169→			<Button
170→				variant="ghost"
171→				size="icon-sm"
172→				class="bg-accent"
173→				title="Board view"
174→				aria-pressed="true"
175→			>
176→				<LayoutGrid class="size-4" />
177→			</Button>
178→			<a href="{base}/tasks" title="List view">
179→				<Button variant="ghost" size="icon-sm" aria-pressed="false">
180→					<List class="size-4" />
181→				</Button>
182→			</a>
183→		</div>
184→	</div>
185→
186→	<!-- Error -->
187→	{#if error}
188→		<div class="mx-6 mt-4 bg-destructive/10 text-destructive p-4 rounded-lg" role="alert" data-testid="board-error">
189→			{error}
190→		</div>
191→	{/if}
192→
193→	<!-- Loading skeleton -->
194→	{#if loading}
195→		<BoardSkeleton />
196→	{:else if tasks.length === 0}
197→		<!-- Empty state -->
198→		<div class="flex flex-col items-center justify-center flex-1 py-16" data-testid="board-empty">
199→			<LayoutGrid class="size-12 text-muted-foreground/30 mb-4" />
200→			<h2 class="text-lg font-medium text-muted-foreground mb-1">No tasks yet</h2>
201→			<p class="text-sm text-muted-foreground">
202→				Create tasks using <code class="bg-muted px-1 rounded text-xs">kspec task add</code>
203→			</p>
204→		</div>
205→	{:else}
206→		<!-- AC: @ui-task-board ac-4 — Active Fleet Row -->
207→		<div class="px-6 pt-4">
208→			<ActiveFleetRow status={agentStatus} outputLines={agentOutputLines} />
209→		</div>
210→
211→		<!-- AC: @ui-task-board ac-1 — Kanban Columns -->
212→		<div class="flex gap-4 overflow-x-auto p-6 pt-2 flex-1 min-h-0" data-testid="board-columns">
213→			{#each columns as column (column.id)}
214→				<BoardColumnComponent {column} onCardClick={handleCardClick} />
215→			{/each}
216→		</div>
217→	{/if}
218→</div>
219→
220→<!-- AC: @ui-task-board ac-3, ac-6 — Detail Modal -->
221→<TaskDetailModal
222→	bind:open={modalOpen}
223→	bind:taskRef={selectedTaskRef}
224→	onTaskUpdated={handleTaskUpdated}
225→/>
