@import "tailwindcss";

@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
 * Kynetic Hub UI Design System
 * Dark-first theme with zinc/orange accent palette
 * Reference: history/HUB_UI_IMPLEMENTATION_PLAN.md
 */

:root {
  --radius: 0.5rem;

  /* Dark theme as default (dark-first design) */
  --background: oklch(0.145 0 0);       /* zinc-950 (#09090b) */
  --foreground: oklch(0.985 0 0);       /* zinc-50 (#fafafa) */
  --card: oklch(0.18 0 0);              /* zinc-900 (#18181b) */
  --card-foreground: oklch(0.985 0 0);  /* zinc-50 */
  --popover: oklch(0.18 0 0);           /* zinc-900 */
  --popover-foreground: oklch(0.985 0 0);

  /* Primary - orange accent */
  --primary: oklch(0.705 0.191 47.6);   /* orange-500 (#f97316) */
  --primary-foreground: oklch(0.145 0 0);

  /* Secondary - zinc tones */
  --secondary: oklch(0.228 0 0);        /* zinc-800 (#27272a) */
  --secondary-foreground: oklch(0.985 0 0);

  /* Muted - for subtle text */
  --muted: oklch(0.228 0 0);            /* zinc-800 */
  --muted-foreground: oklch(0.556 0 0); /* zinc-500 (#71717a) */

  /* Accent - orange */
  --accent: oklch(0.705 0.191 47.6);    /* orange-500 */
  --accent-foreground: oklch(0.145 0 0);
  --accent-dim: oklch(0.553 0.195 38.4); /* orange-700 (#c2410c) */
  --accent-glow: oklch(0.705 0.191 47.6 / 15%);

  /* Borders */
  --border: oklch(0.32 0 0);            /* zinc-700 (#3f3f46) */
  --input: oklch(0.32 0 0);
  --ring: oklch(0.705 0.191 47.6);      /* orange-500 for focus ring */

  /* Destructive */
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.985 0 0);

  /* Chart colors */
  --chart-1: oklch(0.705 0.191 47.6);   /* orange-500 */
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);

  /* Sidebar */
  --sidebar: oklch(0.145 0 0);          /* zinc-950 */
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.705 0.191 47.6);
  --sidebar-primary-foreground: oklch(0.145 0 0);
  --sidebar-accent: oklch(0.228 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(0.32 0 0);
  --sidebar-ring: oklch(0.705 0.191 47.6);

  /*
   * Status Badge Colors
   * Each status has bg, text, and border variants
   */

  /* Draft - dashed zinc */
  --status-draft-bg: oklch(0.32 0 0);
  --status-draft-text: oklch(0.716 0 0);    /* zinc-300 */
  --status-draft-border: oklch(0.32 0 0);

  /* Pending - amber */
  --status-pending-bg: oklch(0.414 0.112 45.9 / 50%);  /* amber-900/50 */
  --status-pending-text: oklch(0.821 0.148 66.3);      /* amber-400 */
  --status-pending-border: oklch(0.555 0.163 48.998 / 50%); /* amber-700/50 */

  /* Ready - emerald */
  --status-ready-bg: oklch(0.359 0.072 163.1 / 50%);   /* emerald-900/50 */
  --status-ready-text: oklch(0.765 0.177 163.2);       /* emerald-400 */
  --status-ready-border: oklch(0.508 0.118 165.6 / 50%); /* emerald-700/50 */

  /* Assigned - blue */
  --status-assigned-bg: oklch(0.379 0.089 254.1 / 50%);  /* blue-900/50 */
  --status-assigned-text: oklch(0.709 0.147 254.6);      /* blue-400 */
  --status-assigned-border: oklch(0.488 0.169 248.1 / 50%); /* blue-700/50 */

  /* Running - orange (pulse animation) */
  --status-running-bg: oklch(0.434 0.16 38.4 / 50%);     /* orange-900/50 */
  --status-running-text: oklch(0.792 0.184 60.6);        /* orange-400 */
  --status-running-border: oklch(0.553 0.195 38.4 / 50%); /* orange-700/50 */

  /* Blocked - red */
  --status-blocked-bg: oklch(0.398 0.141 25.7 / 50%);    /* red-900/50 */
  --status-blocked-text: oklch(0.704 0.191 22.2);        /* red-400 */
  --status-blocked-border: oklch(0.505 0.213 27.5 / 50%); /* red-700/50 */

  /* Completed - emerald */
  --status-completed-bg: oklch(0.359 0.072 163.1 / 50%);
  --status-completed-text: oklch(0.765 0.177 163.2);
  --status-completed-border: oklch(0.508 0.118 165.6 / 50%);

  /* Failed - red */
  --status-failed-bg: oklch(0.398 0.141 25.7 / 50%);
  --status-failed-text: oklch(0.704 0.191 22.2);
  --status-failed-border: oklch(0.505 0.213 27.5 / 50%);

  /* Cancelled - zinc muted */
  --status-cancelled-bg: oklch(0.228 0 0);
  --status-cancelled-text: oklch(0.556 0 0);
  --status-cancelled-border: oklch(0.32 0 0);

  /*
   * Spoke Status Indicators
   */
  --spoke-available: oklch(0.696 0.17 162.5);   /* emerald-500 */
  --spoke-active-secondary: oklch(0.769 0.188 84.4); /* amber-500 */
  --spoke-offline: oklch(0.442 0 0);             /* zinc-600 */
}

/* Light theme (optional - system preference or manual toggle) */
.light {
  --background: oklch(0.985 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.646 0.222 41.1);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.442 0 0);
  --accent: oklch(0.646 0.222 41.1);
  --accent-foreground: oklch(0.985 0 0);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.646 0.222 41.1);
}

@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

/* Active/Focus glow effect for active items */
.active-glow {
  border-color: oklch(0.705 0.191 47.6 / 50%);
  box-shadow: 0 0 20px oklch(0.705 0.191 47.6 / 15%);
  --tw-ring-color: oklch(0.705 0.191 47.6 / 30%);
}

/* Status badge utility classes */
.status-badge-draft {
  background-color: var(--status-draft-bg);
  color: var(--status-draft-text);
  border: 1px dashed var(--status-draft-border);
}

.status-badge-pending {
  background-color: var(--status-pending-bg);
  color: var(--status-pending-text);
  border: 1px solid var(--status-pending-border);
}

.status-badge-ready {
  background-color: var(--status-ready-bg);
  color: var(--status-ready-text);
  border: 1px solid var(--status-ready-border);
}

.status-badge-assigned {
  background-color: var(--status-assigned-bg);
  color: var(--status-assigned-text);
  border: 1px solid var(--status-assigned-border);
}

.status-badge-running {
  background-color: var(--status-running-bg);
  color: var(--status-running-text);
  border: 1px solid var(--status-running-border);
}

.status-badge-blocked {
  background-color: var(--status-blocked-bg);
  color: var(--status-blocked-text);
  border: 1px solid var(--status-blocked-border);
}

.status-badge-completed {
  background-color: var(--status-completed-bg);
  color: var(--status-completed-text);
  border: 1px solid var(--status-completed-border);
}

.status-badge-failed {
  background-color: var(--status-failed-bg);
  color: var(--status-failed-text);
  border: 1px solid var(--status-failed-border);
}

.status-badge-cancelled {
  background-color: var(--status-cancelled-bg);
  color: var(--status-cancelled-text);
  border: 1px solid var(--status-cancelled-border);
}

/*
 * Syntax Highlighting Theme
 * Custom theme matching zinc/orange design system
 * Based on highlight.js class names
 */

/* Keywords, built-ins */
.hljs-keyword,
.hljs-selector-tag,
.hljs-built_in,
.hljs-name,
.hljs-tag {
  color: oklch(0.705 0.191 47.6); /* orange-500 */
}

/* Strings, literals */
.hljs-string,
.hljs-title,
.hljs-section,
.hljs-attribute,
.hljs-literal,
.hljs-template-tag,
.hljs-template-variable,
.hljs-type,
.hljs-addition {
  color: oklch(0.765 0.177 163.2); /* emerald-400 */
}

/* Comments, meta */
.hljs-comment,
.hljs-quote,
.hljs-deletion,
.hljs-meta {
  color: oklch(0.556 0 0); /* zinc-500 */
}

/* Numbers */
.hljs-number,
.hljs-regexp,
.hljs-symbol,
.hljs-variable,
.hljs-link {
  color: oklch(0.821 0.148 66.3); /* amber-400 */
}

/* Functions, classes */
.hljs-title.function_,
.hljs-title.class_ {
  color: oklch(0.709 0.147 254.6); /* blue-400 */
}

/* Parameters, properties */
.hljs-params,
.hljs-property {
  color: oklch(0.871 0 0); /* zinc-200 */
}

/* Attributes in markup */
.hljs-attr {
  color: oklch(0.792 0.184 60.6); /* orange-400 */
}

/* Punctuation, operators */
.hljs-punctuation,
.hljs-operator {
  color: oklch(0.716 0 0); /* zinc-300 */
}

/* Code block emphasis */
.hljs-emphasis {
  font-style: italic;
}

.hljs-strong {
  font-weight: bold;
}

